using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text;
using BLite.Bson;
using BLite.Core;
using BLite.Core.Storage;
using BLite.Core.Transactions;
using BLite.Shared;
using Xunit.Abstractions;

namespace BLite.Tests.Oracles;

/// <summary>
/// Model-based test of a <see cref="DynamicCollection"/> with a non-unique index on <c>count</c> and a
/// unique index on <c>code</c>: the operation sequences of <see cref="StoreModelTests"/> (generated by
/// <see cref="StoreModel"/>), with dynamic-only steps mixed in where no transaction is open:
/// <c>CreateIndexAsync</c> and <c>DropIndex</c> while documents exist, <c>VacuumAsync</c> with and
/// without <c>RebuildIndexes</c> (the dynamic collection's index rebuild), runs of hundreds of
/// documents sharing one indexed value and the delete of all of them. After every step the
/// collection must equal the dictionary model's committed view (scan, count, lookups, the index
/// list), every index must answer through <c>QueryIndexAsync</c> what the model answers, and, when
/// no transaction is open, the pages must add up as in <see cref="WalCrashTests"/>. A failing
/// sequence is shrunk per check, as in <see cref="StoreModelTests"/>.
/// </summary>
/// <remarks>
/// <para>
/// The contract the model encodes is <see cref="StoreModelTests"/>' with the schema-less collection's
/// own rules. A document larger than a page is rejected with <see cref="BLiteValidationException"/>
/// (<c>DynamicCollection.ValidateWrite</c>: "Overflow not yet supported in DynamicCollection"). A
/// unique index rejects a second document with the same value, and an explicit BSON <c>null</c> is a
/// value like any other while a missing field is not indexed (README.md:880, "DynamicCollection
/// indexes an explicit BSON null and rejects a second one"); a null code is therefore written as an
/// explicit null when the id is a multiple of 5 and left out otherwise. Creating an index that
/// exists throws <see cref="InvalidOperationException"/>; creating a unique index over values that
/// are not unique must fail and leave no index behind; <c>DropIndex</c> returns whether the index
/// existed; a vacuum changes no document. The collection has no reads through a transaction, so the
/// pending view is checked only through what the writes accept and reject.
/// </para>
/// <para>
/// Rows are a seed and a check (<c>Model</c>, <c>Index</c>, <c>Index.UniqueBackfill</c>,
/// <c>Pages.Reachable</c>, <c>Pages.FreeList</c>, <c>Pages.Leaked</c>), so a defect in one does not
/// hide the others; a <c>Model</c> failure ends the run, the others are recorded and the run goes on.
/// <c>Index.UniqueBackfill</c> is a unique <c>CreateIndexAsync</c> over values that are not unique
/// that leaves the index registered; the run drops it and goes on. Page accounting
/// walks the primary index and every secondary index from the roots the collection's metadata
/// persists, and the data pages the primary index points at; like <see cref="WalCrashTests"/> it
/// counts only written index pages as leaked, since every reopen and every rollback strands
/// never-written pages (#258, #237).
/// </para>
/// <para>
/// #234 says that deleting N documents that share one indexed value is quadratic. The sequences
/// print the time of every such delete; <see cref="DuplicateDeletes_ScaleLikeNLogN"/> measures the
/// growth from N to 4N and fails when it is more than twice what N log N allows, which no absolute
/// time decides.
/// </para>
/// </remarks>
public class DynamicStoreModelTests
{
    private readonly ITestOutputHelper _output;

    public DynamicStoreModelTests(ITestOutputHelper output) => _output = output;

    private const int Steps = 250;
    private static readonly int[] s_seeds = [1, 2, 3, 4, 5, 6];
    private static readonly PageFileConfig s_config = (PageFileConfig.Small with { PageSize = 4096 }).Normalize();

    internal const string Model = "Model";
    internal const string Index = "Index";
    internal const string PagesReachable = "Pages.Reachable";
    internal const string PagesFreeList = "Pages.FreeList";
    internal const string PagesLeaked = "Pages.Leaked";
    internal const string UniqueBackfill = "Index.UniqueBackfill";
    private static readonly string[] s_checks = [Model, Index, UniqueBackfill, PagesReachable, PagesFreeList, PagesLeaked];

    private const string DeleteScaling = "Duplicates.DeleteScaling";

    private static string Label(int seed, string check) => $"seed {seed} / {check}";

    private static readonly Dictionary<string, (int Seed, string Check)> s_rows =
        (from seed in s_seeds from check in s_checks select (seed, check)).ToDictionary(r => Label(r.seed, r.check));

    public static TheoryData<string> Rows => new(s_rows.Keys);

    /// <summary>
    /// Rows known to fail on upstream 0450b97 plus the oracle branches, see <see cref="Candidates"/>
    /// (draft D9 in <c>Seeds/candidate-issues.md</c>). The page checks pass: <c>DropIndex</c> and
    /// <c>VacuumAsync(RebuildIndexes)</c> free the old trees since #211.
    /// </summary>
    private static readonly Candidates s_candidates = new()
    {
        // D9: CreateIndexAsync registers the index before it fills it and, when a unique violation
        // throws mid-fill, neither unregisters it nor ends the fill's transaction.
        { "a failed unique CreateIndexAsync leaves the half-filled index registered", "",
            Label(3, UniqueBackfill), Label(4, UniqueBackfill), Label(5, UniqueBackfill), Label(6, UniqueBackfill) },
        // #234: dynamic index keys carry no document id, so each delete of a duplicated key searches
        // every leaf that holds the key.
        { "deleting N documents that share an indexed value is quadratic", "#234", DeleteScaling },
    };

    [Fact]
    public void Candidates_NameExistingRows() => s_candidates.AssertAllIn(s_rows.Keys.Append(DeleteScaling));

    // One run per seed serves all of its checks' rows.
    private static readonly ConcurrentDictionary<int, Lazy<Task<RunResult>>> s_runs = new();

    [Theory]
    [MemberData(nameof(Rows))]
    public async Task RandomOperations_MatchTheModel(string row)
    {
        var (seed, check) = s_rows[row];
        var ops = Generate(seed, Steps);
        var run = await s_runs.GetOrAdd(seed, s => new Lazy<Task<RunResult>>(() => Task.Run(() => Replay(ops, null)))).Value;
        foreach (var line in run.Timings) _output.WriteLine(line);

        if (!run.Failures.TryGetValue(check, out var failure))
        {
            s_candidates.Verify(row, null, _output);
            return;
        }

        var shrunk = await Shrink(ops.Take(failure.Step + 1).ToList(), check, TimeSpan.FromSeconds(30));
        var sb = new StringBuilder();
        sb.AppendLine($"{row}: step {failure.Step + 1} of {ops.Count} ({ops[failure.Step]}) failed: {failure.Message}");
        sb.AppendLine($"Shortest failing sequence found ({shrunk.Ops.Count} of {failure.Step + 1} steps), failing at its step {shrunk.Failure.Step + 1}: {shrunk.Failure.Message}");
        for (int i = 0; i < shrunk.Ops.Count; i++)
            sb.AppendLine($"  {i + 1,3}. {shrunk.Ops[i]}");
        s_candidates.Verify(row, sb.ToString(), _output);
    }

    // ── Operations ────────────────────────────────────────────────────────────

    internal enum DynOpKind { Store, CreateIndex, DropIndex, Vacuum, DuplicateRun, DeleteDuplicates }

    /// <summary>A step: one of <see cref="StoreModel"/>'s, or a dynamic-only one.</summary>
    internal sealed record DynOp(DynOpKind Kind, StoreOp? Store = null, string Field = "", bool Flag = false, int Count = 0, int Value = 0)
    {
        public override string ToString() => Kind switch
        {
            DynOpKind.Store => Store!.ToString(),
            DynOpKind.CreateIndex => $"CreateIndex({Field}{(Flag ? ", unique" : "")})",
            DynOpKind.DropIndex => $"DropIndex(idx_{Field})",
            DynOpKind.Vacuum => Flag ? "Vacuum(RebuildIndexes)" : "Vacuum",
            DynOpKind.DuplicateRun => $"DuplicateRun({Count} documents with count={Value})",
            _ => "DeleteDuplicates",
        };
    }

    /// <summary>Ids of the duplicate runs, above <see cref="StoreModel.IdPool"/>.</summary>
    private const int DuplicateIdBase = 1000;

    /// <summary><see cref="StoreModel.Generate"/>'s steps, with a dynamic-only step after about one in seven that leaves no transaction open.</summary>
    internal static List<DynOp> Generate(int seed, int steps)
    {
        var rnd = new Random(seed * 7919 + 17);
        var ops = new List<DynOp>();
        bool open = false, duplicates = false;
        var indexed = new Dictionary<string, bool> { ["count"] = true, ["code"] = true };
        foreach (var op in StoreModel.Generate(seed, steps))
        {
            ops.Add(new DynOp(DynOpKind.Store, op));
            open = op.Kind switch
            {
                StoreOpKind.Begin => true,
                StoreOpKind.Commit or StoreOpKind.Rollback or StoreOpKind.Reopen => false,
                _ => open,
            };
            if (open || rnd.Next(100) >= 15) continue;

            var roll = rnd.Next(100);
            if (roll < 40)
            {
                // Mostly the index that toggles, now and then a create of an existing one or a drop of a missing one.
                var field = rnd.Next(3) == 0 ? "code" : "count";
                var create = roll < 32 ? !indexed[field] : rnd.Next(2) == 0;
                ops.Add(create ? new DynOp(DynOpKind.CreateIndex, Field: field, Flag: field == "code") : new DynOp(DynOpKind.DropIndex, Field: field));
                if (roll < 32) indexed[field] = create;
            }
            else if (roll < 60) ops.Add(new DynOp(DynOpKind.Vacuum, Flag: rnd.Next(2) == 0));
            else
            {
                ops.Add(duplicates ? new DynOp(DynOpKind.DeleteDuplicates, Value: rnd.Next())
                    : new DynOp(DynOpKind.DuplicateRun, Count: rnd.Next(2) == 0 ? 150 : 400, Value: rnd.Next(10)));
                duplicates = !duplicates;
            }
        }
        return ops;
    }

    // ── Replay against the model ──────────────────────────────────────────────

    internal sealed record Failure(int Step, string Message);

    internal sealed class RunResult
    {
        public Dictionary<string, Failure> Failures { get; } = new();
        public List<string> Timings { get; } = new();
    }

    private static async Task<RunResult> Replay(List<DynOp> ops, string? focus)
    {
        var path = Path.Combine(Path.GetTempPath(), $"dyn_store_model_{Guid.NewGuid():N}.db");
        // A directory of its own: a backup writes backup.manifest.json next to it, under that fixed
        // name, and other tests back up into the temp directory at the same time.
        var backupDir = Directory.CreateDirectory(Path.Combine(Path.GetTempPath(), $"dyn_store_model_backup_{Guid.NewGuid():N}")).FullName;
        var backupPath = Path.Combine(backupDir, "backup.db");
        var result = new RunResult();
        var model = new DynamicStoreRunner(path, backupPath, s_config, result.Timings);
        try
        {
            for (int step = 0; step < ops.Count; step++)
            {
                var op = ops[step];
                try
                {
                    await model.ApplyAsync(op);
                    await model.VerifyAsync($"after {op}");
                }
                catch (StoreModelMismatchException ex)
                {
                    result.Failures.TryAdd(Model, new Failure(step, ex.Message));
                    break;
                }
                catch (Exception ex)
                {
                    result.Failures.TryAdd(Model, new Failure(step, $"unexpected {ex.GetType().Name}: {ex.Message}"));
                    break;
                }

                foreach (var (check, message) in model.SideFailures)
                    result.Failures.TryAdd(check, new Failure(step, message));
                model.SideFailures.Clear();
                if (await model.CheckIndexesAsync($"after {op}") is { } indexError)
                    result.Failures.TryAdd(Index, new Failure(step, indexError));
                if (!model.InTransaction)
                    foreach (var (check, message) in model.Account())
                        result.Failures.TryAdd(check, new Failure(step, $"after {op}: {message}"));
                if (focus != null && result.Failures.ContainsKey(focus)) break;
            }
            return result;
        }
        finally
        {
            model.Dispose();
            StoreModel.DeleteDatabase(path);
            try { Directory.Delete(backupDir, recursive: true); } catch { /* best-effort */ }
        }
    }

    private sealed record ShrinkResult(List<DynOp> Ops, Failure Failure);

    /// <summary>
    /// <see cref="StoreModelTests"/>' shrinking, for one check: removes chunks of steps (half, then
    /// quarters, ... down to single steps), keeping a removal if the sequence still fails that check,
    /// until a pass over single steps removes nothing or the time is up. The last step is never removed.
    /// </summary>
    private static async Task<ShrinkResult> Shrink(List<DynOp> ops, string check, TimeSpan budget)
    {
        var sw = Stopwatch.StartNew();
        var current = ops;
        var failure = (await Replay(current, check)).Failures[check];
        int chunk = Math.Max(1, (current.Count - 1) / 2);
        while (sw.Elapsed < budget)
        {
            bool changed = false;
            for (int start = current.Count - 1 - chunk; start >= 0 && sw.Elapsed < budget; start -= chunk)
            {
                var candidate = current.Where((_, j) => j < start || j >= start + chunk).ToList();
                if ((await Replay(candidate, check)).Failures.TryGetValue(check, out var f))
                {
                    current = candidate;
                    failure = f;
                    changed = true;
                }
            }
            if (chunk == 1 && !changed) break;
            if (!changed) chunk = Math.Max(1, chunk / 2);
        }
        return new ShrinkResult(current, failure);
    }

    // ── Deletes of a duplicated value (#234) ──────────────────────────────────

    /// <summary>
    /// Deletes N documents that share one indexed value, and 4N, in a random order and one
    /// transaction (the best of three each), with N documents of distinct values as the control.
    /// Fails when going from N to 4N costs more than twice the growth of N log N.
    /// </summary>
    [Fact]
    public async Task DuplicateDeletes_ScaleLikeNLogN()
    {
        const int small = 1500, large = 12000;
        double dupSmall = await TimeDeletes(small, duplicates: true), dupLarge = await TimeDeletes(large, duplicates: true);
        double distinctSmall = await TimeDeletes(small, duplicates: false), distinctLarge = await TimeDeletes(large, duplicates: false);
        double allowed = (large * Math.Log(large)) / (small * Math.Log(small));
        double growth = dupLarge / dupSmall;
        var measured = $"deleting {small} documents with one indexed value took {dupSmall:F1} ms, {large} took {dupLarge:F1} ms (x{growth:F1}); "
                       + $"with distinct values {distinctSmall:F1} ms and {distinctLarge:F1} ms (x{distinctLarge / distinctSmall:F1}); N log N allows x{allowed:F1}";
        _output.WriteLine(measured);
        s_candidates.Verify(DeleteScaling, growth > 2 * allowed ? $"{DeleteScaling}: the delete of N duplicates grows faster than N log N: {measured}" : null, _output);
    }

    private static async Task<double> TimeDeletes(int n, bool duplicates)
    {
        double best = double.MaxValue;
        for (int attempt = 0; attempt < 3; attempt++)
        {
            var path = Path.Combine(Path.GetTempPath(), $"dyn_dup_delete_{Guid.NewGuid():N}.db");
            try
            {
                using var engine = new BLiteEngine(path, s_config);
                var col = engine.GetOrCreateCollection("dups", BsonIdType.Int32);
                await col.CreateIndexAsync("count");
                await col.InsertBulkAsync(Enumerable.Range(1, n).Select(i => col.CreateDocument(["_id", "count"],
                    b => b.AddId(new BsonId(i)).AddInt32("count", duplicates ? 7 : i))));
                var ids = Enumerable.Range(1, n).OrderBy(_ => Random.Shared.Next()).Select(i => new BsonId(i)).ToList();
                var sw = Stopwatch.StartNew();
                var deleted = await col.DeleteBulkAsync(ids);
                sw.Stop();
                Assert.Equal(n, deleted);
                best = Math.Min(best, sw.Elapsed.TotalMilliseconds);
            }
            finally
            {
                StoreModel.DeleteDatabase(path);
            }
        }
        return best;
    }

    // ── The runner ────────────────────────────────────────────────────────────

    /// <summary>A <see cref="DynamicCollection"/> and the dictionary model it is checked against.</summary>
    private sealed class DynamicStoreRunner : IDisposable
    {
        private const string Collection = "store_docs";
        private static readonly string[] s_keys = ["_id", "name", "count", "code", "payload"];

        private readonly string _path;
        private readonly string _backupPath;
        private readonly PageFileConfig _config;
        private readonly List<string> _timings;
        private Dictionary<int, StoreDoc> _committed = new();
        private Dictionary<int, StoreDoc> _pending = new();
        private readonly HashSet<string> _indexes = ["count", "code"];
        private ITransaction? _tx;
        private int _duplicateValue;
        private BLiteEngine _engine;
        private DynamicCollection _col;

        public DynamicStoreRunner(string path, string backupPath, PageFileConfig config, List<string> timings)
        {
            _path = path;
            _backupPath = backupPath;
            _config = config;
            _timings = timings;
            _engine = new BLiteEngine(path, config);
            _col = _engine.GetOrCreateCollection(Collection, BsonIdType.Int32);
            _col.CreateIndexAsync("count").GetAwaiter().GetResult();
            _col.CreateIndexAsync("code", unique: true).GetAwaiter().GetResult();
        }

        public bool InTransaction => _tx != null;

        /// <summary>Failures of a check other than <see cref="Model"/> found while applying a step, which the run survives.</summary>
        public List<(string Check, string Message)> SideFailures { get; } = new();

        public void Dispose()
        {
            _tx?.Dispose();
            _engine.Dispose();
        }

        private Dictionary<int, StoreDoc> View() => _tx != null ? _pending : _committed;

        // ── Documents ──────────────────────────────────────────────────────────

        /// <summary>A null code is an explicit BSON null for ids that are multiples of 5 (not in duplicate runs), a missing field otherwise.</summary>
        private static bool ExplicitNull(StoreDoc d) => d.Code == null && d.Id < DuplicateIdBase && d.Id % 5 == 0;

        /// <summary>The value the unique index holds for the document: its code, DBNull for an explicit null, nothing for a missing field.</summary>
        private static object? UniqueKey(StoreDoc d) => d.Code ?? (ExplicitNull(d) ? DBNull.Value : (object?)null);

        private BsonDocument ToBson(StoreDoc d) => _col.CreateDocument(s_keys, b =>
        {
            b.AddId(new BsonId(d.Id));
            b.AddString("name", d.Name);
            b.AddInt32("count", d.Count);
            if (d.Code != null) b.AddString("code", d.Code);
            else if (ExplicitNull(d)) b.AddNull("code");
            b.AddString("payload", d.Payload);
        });

        private static StoreDoc FromBson(BsonDocument doc)
        {
            doc.TryGetValue("code", out var code);
            return new StoreDoc
            {
                Id = doc.GetValue("_id").AsInt32,
                Name = doc.GetValue("name").AsString,
                Count = doc.GetValue("count").AsInt32,
                Code = code.IsNull ? null : code.AsString,
                Payload = doc.GetValue("payload").AsString,
            };
        }

        private static async IAsyncEnumerable<StoreDoc> Docs(IAsyncEnumerable<BsonDocument> docs)
        {
            await foreach (var d in docs) yield return FromBson(d);
        }

        /// <summary>A document that does not fit in one page (DynamicCollection._maxDocumentSizeForSinglePage).</summary>
        private bool TooLarge(StoreDoc d) => ToBson(d).RawData.Length + SlotEntry.Size > _engine.Storage.PageSize - 128;

        private bool UniqueTaken(StoreDoc d)
            => _indexes.Contains("code") && UniqueKey(d) is { } key && View().Values.Any(o => o.Id != d.Id && Equals(UniqueKey(o), key));

        private string? Rejection(StoreDoc d, bool insert)
            => insert && View().ContainsKey(d.Id) ? "the duplicate id"
                : TooLarge(d) ? "a document larger than a page"
                : UniqueTaken(d) ? "the duplicate unique code" : null;

        // ── Steps ──────────────────────────────────────────────────────────────

        public async Task ApplyAsync(DynOp op)
        {
            if (op.Kind == DynOpKind.Store)
            {
                await ApplyStoreAsync(op.Store!);
                return;
            }
            // The index and vacuum calls take no transaction; after shrinking one can land inside one.
            if (_tx != null) return;
            switch (op.Kind)
            {
                case DynOpKind.CreateIndex:
                {
                    var name = $"idx_{op.Field}";
                    if (_indexes.Contains(op.Field))
                    {
                        await ExpectThrows<InvalidOperationException>(() => _col.CreateIndexAsync(op.Field, unique: op.Flag), op, "an index that exists");
                    }
                    else if (op.Flag && _committed.Values.Select(UniqueKey).Where(k => k != null).GroupBy(k => k).Any(g => g.Count() > 1))
                    {
                        await ExpectThrows<InvalidOperationException>(() => _col.CreateIndexAsync(op.Field, unique: true), op, "values that are not unique");
                        // Reported as a check of its own; the index is dropped so that the run can go on.
                        if (_col.ListIndexes().Contains(name))
                        {
                            SideFailures.Add((UniqueBackfill, $"{op} threw for values that are not unique and left '{name}' registered, half filled"));
                            _col.DropIndex(name);
                        }
                    }
                    else
                    {
                        await _col.CreateIndexAsync(op.Field, unique: op.Flag);
                        _indexes.Add(op.Field);
                    }
                    break;
                }
                case DynOpKind.DropIndex:
                {
                    var dropped = _col.DropIndex($"idx_{op.Field}");
                    var expected = _indexes.Remove(op.Field);
                    StoreModel.Check(dropped == expected, $"{op} returned {dropped}, expected {expected}");
                    break;
                }
                case DynOpKind.Vacuum:
                    await _col.VacuumAsync(new VacuumOptions { RebuildIndexes = op.Flag });
                    break;
                case DynOpKind.DuplicateRun:
                {
                    var docs = Enumerable.Range(DuplicateIdBase, op.Count).Where(id => !_committed.ContainsKey(id))
                        .Select(id => new StoreDoc { Id = id, Name = "dup", Count = op.Value, Payload = "" }).ToList();
                    var sw = Stopwatch.StartNew();
                    var ids = await _col.InsertBulkAsync(docs.Select(ToBson));
                    sw.Stop();
                    StoreModel.Check(ids.Count == docs.Count, $"{op} inserted {ids.Count} documents, expected {docs.Count}");
                    foreach (var d in docs) _committed[d.Id] = d;
                    _duplicateValue = op.Value;
                    _timings.Add($"{op}: inserted {docs.Count} in {sw.Elapsed.TotalMilliseconds:F1} ms");
                    break;
                }
                case DynOpKind.DeleteDuplicates:
                {
                    var rnd = new Random(op.Value);
                    var ids = _committed.Keys.Where(id => id >= DuplicateIdBase).OrderBy(_ => rnd.Next()).ToList();
                    if (ids.Count == 0) break;
                    var sw = Stopwatch.StartNew();
                    var deleted = await _col.DeleteBulkAsync(ids.Select(id => new BsonId(id)));
                    sw.Stop();
                    StoreModel.Check(deleted == ids.Count, $"{op} returned {deleted}, expected {ids.Count}");
                    foreach (var id in ids) _committed.Remove(id);
                    _timings.Add($"{op}: deleted {ids.Count} documents sharing count={_duplicateValue} in {sw.Elapsed.TotalMilliseconds:F1} ms"
                                 + (_indexes.Contains("count") ? "" : " (no index on count)"));
                    break;
                }
            }
        }

        private async Task ApplyStoreAsync(StoreOp op)
        {
            switch (op.Kind)
            {
                case StoreOpKind.Insert:
                {
                    var d = StoreModel.Clone(op.Docs![0]);
                    if (Rejection(d, insert: true) is { } why)
                    {
                        await ExpectRejected(() => _col.InsertAsync(ToBson(d), _tx).AsTask(), op, why);
                        break;
                    }
                    var id = await _col.InsertAsync(ToBson(d), _tx);
                    StoreModel.Check(id == new BsonId(d.Id), $"{op} returned id {id}");
                    View()[d.Id] = d;
                    break;
                }
                case StoreOpKind.Update:
                {
                    var d = StoreModel.Clone(op.Docs![0]);
                    if (!View().ContainsKey(d.Id))
                    {
                        var updated = await _col.UpdateAsync(new BsonId(d.Id), ToBson(d), _tx);
                        StoreModel.Check(!updated, $"{op} returned true for a document that does not exist");
                    }
                    else if (Rejection(d, insert: false) is { } why)
                    {
                        await ExpectRejected(() => _col.UpdateAsync(new BsonId(d.Id), ToBson(d), _tx).AsTask(), op, why);
                    }
                    else
                    {
                        var updated = await _col.UpdateAsync(new BsonId(d.Id), ToBson(d), _tx);
                        StoreModel.Check(updated, $"{op} returned false for an existing document");
                        View()[d.Id] = d;
                    }
                    break;
                }
                case StoreOpKind.Delete:
                {
                    var deleted = await _col.DeleteAsync(new BsonId(op.Id), _tx);
                    var expected = View().Remove(op.Id);
                    StoreModel.Check(deleted == expected, $"{op} returned {deleted}, expected {expected}");
                    break;
                }
                case StoreOpKind.Upsert:
                {
                    var d = StoreModel.Clone(op.Docs![0]);
                    if (Rejection(d, insert: false) is { } why)
                    {
                        await ExpectRejected(() => _col.UpsertAsync(ToBson(d), _tx).AsTask(), op, why);
                        break;
                    }
                    var result = await _col.UpsertAsync(ToBson(d), _tx);
                    var expectedInserted = !View().ContainsKey(d.Id);
                    StoreModel.Check(result.Inserted == expectedInserted, $"{op} reported Inserted={result.Inserted}, expected {expectedInserted}");
                    StoreModel.Check(result.Id == new BsonId(d.Id), $"{op} returned id {result.Id}");
                    View()[d.Id] = d;
                    break;
                }
                case StoreOpKind.InsertBulk:
                {
                    // Only documents the model accepts: free ids, fitting in a page, unique values free among them too.
                    var batch = new List<StoreDoc>();
                    foreach (var d in op.Docs!.Select(StoreModel.Clone))
                        if (Rejection(d, insert: true) == null
                            && (!_indexes.Contains("code") || UniqueKey(d) is not { } key || batch.All(b => !Equals(UniqueKey(b), key))))
                            batch.Add(d);
                    if (batch.Count == 0) break;
                    var ids = await _col.InsertBulkAsync(batch.Select(ToBson), _tx);
                    StoreModel.Check(ids.SequenceEqual(batch.Select(b => new BsonId(b.Id))), $"{op} returned ids [{string.Join(",", ids)}]");
                    foreach (var d in batch) View()[d.Id] = d;
                    break;
                }
                case StoreOpKind.DeleteBulk:
                {
                    var deleted = await _col.DeleteBulkAsync(op.Ids!.Select(id => new BsonId(id)), _tx);
                    int expected = 0;
                    foreach (var id in op.Ids!) if (View().Remove(id)) expected++;
                    StoreModel.Check(deleted == expected, $"{op} returned {deleted}, expected {expected}");
                    break;
                }
                case StoreOpKind.FindById:
                {
                    var found = await _col.FindByIdAsync(new BsonId(op.Id));
                    StoreModel.CheckDoc(_committed.GetValueOrDefault(op.Id), found == null ? null : FromBson(found), $"{op} (no transaction)");
                    break;
                }
                case StoreOpKind.Begin:
                    if (_tx != null) break;
                    _tx = await _engine.BeginTransactionAsync();
                    _pending = _committed.ToDictionary(kv => kv.Key, kv => StoreModel.Clone(kv.Value));
                    break;
                case StoreOpKind.Commit:
                    if (_tx == null) break;
                    await _tx.CommitAsync();
                    StoreModel.Check(_tx.State == TransactionState.Committed, $"{op}: transaction state is {_tx.State} after CommitAsync");
                    _tx.Dispose(); _tx = null;
                    _committed = _pending;
                    break;
                case StoreOpKind.Rollback:
                    if (_tx == null) break;
                    await _tx.RollbackAsync();
                    _tx.Dispose(); _tx = null;
                    break;
                case StoreOpKind.Checkpoint:
                    await _engine.CheckpointAsync();
                    break;
                case StoreOpKind.Backup:
                {
                    StoreModel.DeleteDatabase(_backupPath);
                    await _engine.BackupAsync(_backupPath);
                    using var copy = new BLiteEngine(_backupPath, _config);
                    StoreModel.Check(copy.ListCollections().Contains(Collection), $"{op}: the backup has no collection '{Collection}'");
                    var col = copy.GetOrCreateCollection(Collection, BsonIdType.Int32);
                    var contents = await StoreModel.ReadAll(Docs(col.FindAllAsync()));
                    StoreModel.CheckSame(_committed, contents, "the backup");
                    CheckIndexList(col.ListIndexes(), "the backup");
                    break;
                }
                case StoreOpKind.Reopen:
                    _tx?.Dispose(); _tx = null;
                    _engine.Dispose();
                    _engine = new BLiteEngine(_path, _config);
                    _col = _engine.GetOrCreateCollection(Collection, BsonIdType.Int32);
                    break;
            }
        }

        private async Task ExpectRejected(Func<Task> write, StoreOp op, string why)
        {
            var stateBefore = _tx?.State;
            try
            {
                await write();
                StoreModel.Fail($"{op} should have thrown BLiteValidationException for {why}");
            }
            catch (BLiteValidationException) { }
            catch (StoreModelMismatchException) { throw; }
            catch (Exception ex) { StoreModel.Fail($"{op} threw {ex.GetType().Name} instead of BLiteValidationException for {why}: {ex.Message}"); }
            if (_tx != null)
                StoreModel.Check(_tx.State == TransactionState.Active, $"{op}: a BLiteValidationException must leave the transaction active, state is {_tx.State} (was {stateBefore})");
        }

        private static async Task ExpectThrows<T>(Func<Task> call, DynOp op, string why) where T : Exception
        {
            try
            {
                await call();
                StoreModel.Fail($"{op} should have thrown {typeof(T).Name} for {why}");
            }
            catch (T) { }
            catch (StoreModelMismatchException) { throw; }
            catch (Exception ex) { StoreModel.Fail($"{op} threw {ex.GetType().Name} instead of {typeof(T).Name} for {why}: {ex.Message}"); }
        }

        // ── Checks ─────────────────────────────────────────────────────────────

        private void CheckIndexList(IReadOnlyList<string> actual, string what)
        {
            var expected = _indexes.Select(f => $"idx_{f}").Order().ToList();
            var got = actual.Order().ToList();
            StoreModel.Check(expected.SequenceEqual(got), $"{what}: the collection lists the indexes [{string.Join(", ", got)}], the model has [{string.Join(", ", expected)}]");
        }

        /// <summary>The committed view: scan, count, a lookup of every id the model knows, the index list.</summary>
        public async Task VerifyAsync(string when)
        {
            var scanned = await StoreModel.ReadAll(Docs(_col.FindAllAsync()));
            StoreModel.CheckSame(_committed, scanned, $"{when}: FindAllAsync (committed view)");
            var count = await _col.CountAsync();
            StoreModel.Check(count == _committed.Count, $"{when}: CountAsync returned {count}, the model has {_committed.Count} committed documents");
            CheckIndexList(_col.ListIndexes(), when);
        }

        /// <summary>Every index through QueryIndexAsync against the committed view: equalities, a range, the whole index.</summary>
        public async Task<string?> CheckIndexesAsync(string when)
        {
            async Task<string?> Query(string index, object? min, object? max, Func<StoreDoc, bool> expected, string what)
            {
                var got = new List<int>();
                await foreach (var d in _col.QueryIndexAsync(index, min, max)) got.Add(d.GetValue("_id").AsInt32);
                got.Sort();
                var exp = _committed.Values.Where(expected).Select(d => d.Id).Order().ToList();
                if (got.SequenceEqual(exp)) return null;
                var missing = exp.Except(got).ToList();
                var extra = got.Except(exp).ToList();
                var twice = got.GroupBy(i => i).Where(g => g.Count() > 1).Select(g => g.Key).ToList();
                return $"{when}: QueryIndexAsync(\"{index}\", {what}) returned {got.Count} documents, the model has {exp.Count}; "
                       + $"missing [{string.Join(",", missing.Take(20))}], unexpected [{string.Join(",", extra.Take(20))}], twice [{string.Join(",", twice.Take(20))}]";
            }

            if (_indexes.Contains("count"))
            {
                for (int k = 0; k < 10; k++)
                {
                    var kk = k;
                    if (await Query("idx_count", kk, kk, d => d.Count == kk, $"{kk}, {kk}") is { } e) return e;
                }
                if (await Query("idx_count", 3, 6, d => d.Count is >= 3 and <= 6, "3, 6") is { } range) return range;
                if (await Query("idx_count", null, null, _ => true, "null, null") is { } all) return all;
            }
            if (_indexes.Contains("code"))
            {
                foreach (var code in _committed.Values.Select(d => d.Code).Where(c => c != null).Distinct().Order().Take(3))
                    if (await Query("idx_code", code, code, d => d.Code == code, $"\"{code}\", \"{code}\"") is { } e) return e;
                if (await Query("idx_code", DBNull.Value, DBNull.Value, ExplicitNull, "DBNull, DBNull") is { } nulls) return nulls;
                if (await Query("idx_code", null, null, d => UniqueKey(d) != null, "null, null") is { } all) return all;
            }
            return null;
        }

        /// <summary>
        /// The pages, as <c>WalCrashTests.Account</c> counts them: what the primary index, the
        /// secondary indexes (from the roots the metadata persists) and the documents reach is not
        /// free, the free list is a sound chain of exactly the pages marked free, and no written index
        /// page is neither reached nor free.
        /// </summary>
        public IEnumerable<(string Check, string Message)> Account()
        {
            var storage = _engine.Storage;
            storage.PendingFreeCheckpointCompletion.GetAwaiter().GetResult();
            var count = storage.PageCount;
            var page = new byte[storage.PageSize];

            var types = new PageType[count];
            for (uint p = 0; p < count; p++)
            {
                storage.ReadPageHeader(p, null, page.AsSpan(0, 32));
                types[p] = PageHeader.ReadFrom(page).PageType;
            }
            var freeMarked = Enumerable.Range(1, (int)count - 1).Select(p => (uint)p).Where(p => types[p] == PageType.Free).ToHashSet();
            var listed = storage.GetCollectionPageIds(Collection).ToHashSet();
            var pending = Enumerable.Range(0, (int)count).Select(p => (uint)p).Where(p => !listed.Contains(p)).ToHashSet();

            var chain = new List<uint>();
            string? chainError = null;
            storage.ReadPageHeader(0, null, page.AsSpan(0, 32));
            var seen = new HashSet<uint>();
            for (var next = PageHeader.ReadFrom(page).NextPageId; next != 0;)
            {
                if (next >= count) { chainError = $"the free list points past the end of the file ({count} pages) at page {next}"; break; }
                if (!seen.Add(next)) { chainError = $"the free list loops back to page {next} after {chain.Count} pages"; break; }
                chain.Add(next);
                if (types[next] != PageType.Free) { chainError = $"page {next}, on the free list after {chain.Count - 1} pages, has type {types[next]}"; break; }
                storage.ReadPageHeader(next, null, page.AsSpan(0, 32));
                next = PageHeader.ReadFrom(page).NextPageId;
            }

            var metadata = storage.GetCollectionMetadata(Collection);
            var owner = new Dictionary<uint, string>();
            var dataPages = new HashSet<uint>();
            var locations = new List<DocumentLocation>();
            string? reachError = metadata == null ? $"no metadata for collection '{Collection}'"
                : WalCrashTests.Walk(storage, metadata.PrimaryRootPageId, "the primary index", owner, locations);
            if (reachError == null)
            {
                var persisted = metadata!.Indexes.Select(i => i.Name).Order().ToList();
                var expected = _indexes.Select(f => $"idx_{f}").Order().ToList();
                if (!persisted.SequenceEqual(expected))
                    reachError = $"the metadata lists the indexes [{string.Join(", ", persisted)}], the model has [{string.Join(", ", expected)}]";
            }
            foreach (var index in metadata?.Indexes ?? [])
                if (reachError == null)
                    reachError = WalCrashTests.Walk(storage, index.RootPageId, $"index '{index.Name}'", owner, null);
            foreach (var location in locations)
            {
                if (reachError != null) break;
                reachError = WalCrashTests.WalkDocument(storage, location, owner, dataPages);
            }
            if (reachError == null)
            {
                foreach (var p in owner.Keys.Concat(dataPages).Order())
                {
                    if (freeMarked.Contains(p)) { reachError = $"page {p}, reached from {owner.GetValueOrDefault(p, "a document")}, is on the free list"; break; }
                    if (pending.Contains(p)) { reachError = $"page {p}, reached from {owner.GetValueOrDefault(p, "a document")}, is queued to be freed"; break; }
                }
            }
            if (reachError != null) yield return (PagesReachable, reachError);

            var freeError = chainError;
            if (freeError == null)
            {
                var unlisted = freeMarked.Except(chain).Order().ToList();
                if (unlisted.Count > 0) freeError = $"{unlisted.Count} pages are marked free but not on the free list: {WalCrashTests.Pages(unlisted)}";
            }
            if (freeError != null) yield return (PagesFreeList, freeError);

            if (reachError == null)
            {
                var leaked = Enumerable.Range(1, (int)count - 1).Select(p => (uint)p)
                    .Where(p => types[p] is PageType.Index or PageType.Overflow && !owner.ContainsKey(p) && !pending.Contains(p))
                    .ToList();
                if (leaked.Count > 0)
                    yield return (PagesLeaked, $"{leaked.Count} of the {count} pages are index or overflow pages that nothing reaches and that are not free: "
                        + WalCrashTests.Pages(leaked));
            }
        }
    }
}
